public class EscapeAnalysisDemo {
    public int computeSum(int x, int y) {
        // Point is locally instantiated and never escapes this frame.
        // Escape analysis will trigger scalar replacement, breaking 'p'
        // down into primitive integers 'a' and 'b', avoiding heap allocation.
        Point p = new Point(x, y);
        return p.x + p.y;
    }

    private static class Point {
        int x;
        int y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}
